package cl.duoc.tienda.proveedor.service;
import cl.duoc.tienda.proveedor.dto.*; import cl.duoc.tienda.proveedor.model.*; import cl.duoc.tienda.proveedor.repository.*; import java.util.*; import org.slf4j.*; import org.springframework.stereotype.Service;
@Service public class ProveedorService { private static final Logger log=LoggerFactory.getLogger(ProveedorService.class); private final ProveedorRepository repo; public ProveedorService(ProveedorRepository r){repo=r;} public List<Proveedor> listar(){return repo.findAll();} public Proveedor buscar(Long id){return repo.findById(id).orElseThrow(()->new NoSuchElementException("Proveedor no encontrado: "+id));} public Proveedor guardar(ProveedorRequest d){ Proveedor e=new Proveedor(d.nombre(), d.email()); log.info("Guardando proveedor"); return repo.save(e);} public Proveedor actualizar(Long id,ProveedorRequest d){buscar(id); Proveedor e=new Proveedor(d.nombre(), d.email()); e.setId(id); return repo.save(e);} public void eliminar(Long id){buscar(id);repo.deleteById(id);log.info("Proveedor eliminado: {}",id);} }
